import { z } from "zod";

// Payment references are generated by the server: "AVIVPAY-" and 128 random bits in hex.
export const paymentReferenceSchema = z.object({
  reference: z.string().regex(/^AVIVPAY-[a-f0-9]{32}$/),
});

export type PaymentStartResult =
  | { status: "redirect"; url: string }
  | {
      status:
        "paid" | "expired" | "unavailable" | "rate_limited" | "not_configured" | "infrastructure";
    };

// paid: recorded; late: paid after the time had gone; duplicate: already paid; review: needs AVIV;
// not_paid: Paystack has no successful payment; unknown: not a reference this site issued.
export type PaymentCheckResult = {
  status:
    | "paid"
    | "late"
    | "duplicate"
    | "review"
    | "not_paid"
    | "unknown"
    | "rate_limited"
    | "not_configured"
    | "infrastructure";
};

// Where the return page sends the guest afterwards. Kept only in this browser tab.
export const LAST_BOOKING_KEY = "aviv-last-booking";
